import {PlayIcon, type Icon, PackageIcon, CodeSquareIcon, CopilotIcon} from '@primer/octicons-react'
import {Heading, Label, NavList} from '@primer/react'
import {testIdProps} from '@github-ui/test-id-props'

import styles from './InsightsSidenav.module.css'
import {clsx} from 'clsx'

export interface InsightsSidenavProps {
  selectedKey?:
    | 'dependency_insights'
    | 'actions_usage_metrics'
    | 'actions_performance_metrics'
    | 'api'
    | 'copilot_metrics_usage'
    | 'copilot_metrics_code_generation'
    | 'copilot_metrics_impact'
  /* the show- properties are only needed when something has to be hidden at times (i.e. FF) */
  showDependencies?: boolean
  urls: {[key: string]: string}
  showActionsUsageMetrics?: boolean
  showApi?: boolean
  showCopilotUsage?: boolean
  showCopilotCodeGeneration?: boolean
  showCopilotImpact?: boolean
}

export const InsightsSidenav = ({
  selectedKey,
  showDependencies,
  urls,
  showActionsUsageMetrics,
  showApi,
  showCopilotUsage,
  showCopilotCodeGeneration,
  showCopilotImpact,
}: InsightsSidenavProps) => {
  const impactGroup: InsightsSideNavItem[] = []
  const copilotGroup: InsightsSideNavItem[] = []
  const actionsGroup: InsightsSideNavItem[] = []
  const otherGroup: InsightsSideNavItem[] = []

  if (showCopilotImpact) {
    const copilotMetricsImpactKey = 'copilot_metrics_impact'
    impactGroup.push({
      display: 'Copilot impact',
      key: copilotMetricsImpactKey,
      href: urls[copilotMetricsImpactKey] || '#',
      selected: selectedKey === copilotMetricsImpactKey,
      icon: CopilotIcon,
      beta: false,
    })
  }

  if (showCopilotUsage) {
    const copilotMetricsUsageKey = 'copilot_metrics_usage'
    copilotGroup.push({
      display: 'Copilot usage',
      key: copilotMetricsUsageKey,
      href: urls[copilotMetricsUsageKey] || '#',
      selected: selectedKey === copilotMetricsUsageKey,
      icon: CopilotIcon,
      beta: false,
    })
  }

  if (showCopilotCodeGeneration) {
    const copilotMetricsCodeGenKey = 'copilot_metrics_code_generation'
    copilotGroup.push({
      display: 'Code generation',
      key: copilotMetricsCodeGenKey,
      href: urls[copilotMetricsCodeGenKey] || '#',
      selected: selectedKey === copilotMetricsCodeGenKey,
      icon: CopilotIcon,
      beta: false,
    })
  }

  if (showActionsUsageMetrics) {
    const actionsUsageMetricsKey = 'actions_usage_metrics'
    const actionsPerformanceMetricsKey = 'actions_performance_metrics'
    actionsGroup.push({
      display: 'Actions Usage Metrics',
      key: actionsUsageMetricsKey,
      href: urls[actionsUsageMetricsKey] || '#',
      selected: selectedKey === actionsUsageMetricsKey,
      icon: PlayIcon,
    })
    actionsGroup.push({
      display: 'Actions Performance Metrics',
      key: actionsPerformanceMetricsKey,
      href: urls[actionsPerformanceMetricsKey] || '#',
      selected: selectedKey === actionsPerformanceMetricsKey,
      icon: PlayIcon,
    })
  }

  if (showDependencies) {
    const dependencyKey = 'dependency_insights'
    otherGroup.push({
      display: 'Dependencies',
      key: dependencyKey,
      href: urls[dependencyKey] || '#',
      selected: selectedKey === dependencyKey,
      icon: PackageIcon,
    })
  }

  if (showApi) {
    const apiKey = 'api'
    otherGroup.push({
      display: 'REST API',
      key: apiKey,
      href: urls[apiKey] || '#',
      selected: selectedKey === apiKey,
      icon: CodeSquareIcon,
      beta: false,
    })
  }

  const groups = [impactGroup, copilotGroup, actionsGroup, otherGroup].filter(group => group.length > 0)

  const renderItem = (item: InsightsSideNavItem) => (
    <NavList.Item key={item.key} href={item.href} aria-current={item.selected}>
      <NavList.LeadingVisual>
        <item.icon />
      </NavList.LeadingVisual>
      {item.display}
      {item.beta && (
        <NavList.TrailingVisual>
          <Label variant="success">Preview</Label>
        </NavList.TrailingVisual>
      )}
    </NavList.Item>
  )

  return (
    <div className={styles.InsightsSidenav} {...testIdProps('InsightsSidenav')}>
      <Heading as="h2" variant="medium" className={styles.insightsHeading}>
        Insights
      </Heading>
      <NavList aria-label="Insights navigation">
        {groups.map(group => (
          <NavList.Group key={group[0]?.key}>{group.map(renderItem)}</NavList.Group>
        ))}
      </NavList>
    </div>
  )
}

export const InsightsSidenavPanel = (props: InsightsSidenavProps) => {
  return (
    <div className={clsx(styles.InsightsSidenavPanel, 'border-lg-right')}>
      <InsightsSidenav {...props} />
    </div>
  )
}

interface InsightsSideNavItem {
  key: string
  href: string
  display: string
  selected?: boolean
  icon: Icon
  beta?: boolean
}
